def recommend_auth(scenario):
    if scenario == "quick-test":
        return "basic"
    elif scenario == "public-api":
        return "api-key"
    elif scenario == "stateless-sso":
        return "jwt"
    elif scenario == "third-party-login":
        return "oauth2"
    else:
        return "unknown"

